{"file_path":"tests/test_metrics.py","content":"import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_basic():
    assert conversion_rate([{"converted": True}, {"converted": False}]) == 0.5


def test_conversion_rate_counts_none_as_not_converted():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5


def test_conversion_rate_empty():
    assert conversion_rate([]) == 0.0


def test_pooled_conversion_rate_weights_sessions_not_groups():
    groups = {
        "a": [{"converted": True}],
        "b": [{"converted": False}, {"converted": None}, {"converted": False}],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({"empty": []}) == 0.0
    assert pooled_conversion_rate({}) == 0.0


@pytest.mark.parametrize(("days", "expected"), [(0, 0), (1, 4), (2, 6), (10, 7)])
def test_conversions_in_window(days, expected):
    assert conversions_in_window([1, 2, 4], days) == expected


def test_parse_session_log_flags_and_skipped_lines():
    lines = ["", " \t\n", "  # comment", " x1 , 3 , 1 ", "x2,4,0", "x3,5,  "]
    assert parse_session_log(lines) == [
        {"id": "x1", "day": 3, "converted": True},
        {"id": "x2", "day": 4, "converted": False},
        {"id": "x3", "day": 5, "converted": None},
    ]


@pytest.mark.parametrize("bad_line", ["x1,3", "x1,3,1,extra", "x1,no-day,1"])
def test_parse_session_log_errors_report_input_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_session_log(["", " # comment", "x0,1,0", bad_line])


def test_dedupe_sessions_keeps_last_record_and_sorts_by_day_then_id():
    original = {"id": "b", "day": 5, "converted": False}
    replacement = {"id": "b", "day": 2, "converted": True}
    same_day = {"id": "a", "day": 2, "converted": False}
    earlier_day = {"id": "z", "day": 1, "converted": True}
    assert dedupe_sessions([original, same_day, earlier_day, replacement]) == [
        earlier_day, same_day, replacement,
    ]


def test_daily_conversion_counts_include_boundaries_and_fill_gaps():
    events = parse_session_log([
        "a,0,1", "b,1,1", "c,1,1", "d,2,0", "e,2,", "f,4,1", "g,5,1",
    ])
    assert daily_conversion_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_conversion_counts(events, 4, 1) == []


def test_campaign_summary_uses_calendar_days_and_nonempty_groups():
    groups = {"a": parse_session_log(["x,1,1"]), "b": parse_session_log(["y,3,1", "z,5,0"]), "c": []}
    assert campaign_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert campaign_summary(groups, 3) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert campaign_summary({"c": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"b": [{"converted": True}], "empty": [], "a": [{"converted": True}], "c": [{"converted": False}]}
    assert top_converting_groups(groups, 1) == ["a"]
    assert top_converting_groups(groups, 10) == ["a", "b", "c"]


def test_conversion_rate_by_group_orders_names_and_marks_empty_groups():
    groups = {"z": [{"converted": None}], "b": [], "a": [{"converted": True}]}
    assert list(conversion_rate_by_group(groups).items()) == [("a", 1.0), ("b", None), ("z", 0.0)]


def test_longest_conversion_streak_resets_at_nonpositive_counts():
    assert longest_conversion_streak([1, 1, 0, 2, 3, 4, -1, 1]) == 3
    assert longest_conversion_streak([0, -1]) == 0
    assert longest_conversion_streak([]) == 0
